/// Identical to ComparisonListType but supports argument instance references.
#[derive(Debug, Clone, PartialEq, Default)]
pub struct ArgumentComparisonListType {
    /// List of Comparison elements must all be true for the comparison to
    /// evaluate to true.
    pub comparison: Vec<ArgumentComparisonType>,
}

impl XmlElement for ArgumentComparisonListType {
    fn write_xml(&self, w: &mut Writer<'_>, tag: &str) -> Result<()> {
        w.start(tag);
        check_count(
            self.comparison.len(),
            1,
            None,
            "ArgumentComparisonListType.Comparison",
        )?;
        for v in &self.comparison {
            v.write_xml(w, "Comparison")?;
        }
        w.end(tag);
        Ok(())
    }

    fn read_xml<'a>(r: &mut Reader<'a>, tag: &Tag<'a>) -> Result<Self> {
        let mut v = Self::default();
        for a in tag.attrs() {
            let (k, _) = a?;
            r.unknown_attr(tag, k)?;
        }
        while r.peek_child()? == Some("Comparison") {
            v.comparison.push(r.read_child()?);
        }
        if v.comparison.len() < 1 {
            let n = v.comparison.len();
            return Err(r.too_few("Comparison", 1, n));
        }
        r.close()?;
        Ok(v)
    }
}

