/// Defines a list of argument values that restrict a constraint from being
/// realized in the commanding lifecycle.
#[derive(Debug, Clone, PartialEq, Default)]
pub struct ArgumentRestrictionListType {
    /// Specifies an argument value that causes this constraint to be realized.
    pub argument_restriction: Vec<ArgumentAssignmentType>,
}

impl XmlElement for ArgumentRestrictionListType {
    fn write_xml(&self, w: &mut Writer<'_>, tag: &str) -> Result<()> {
        w.start(tag);
        check_count(
            self.argument_restriction.len(),
            1,
            None,
            "ArgumentRestrictionListType.ArgumentRestriction",
        )?;
        for v in &self.argument_restriction {
            v.write_xml(w, "ArgumentRestriction")?;
        }
        w.end(tag);
        Ok(())
    }

    fn read_xml<'a>(r: &mut Reader<'a>, tag: &Tag<'a>) -> Result<Self> {
        let mut v = Self::default();
        for a in tag.attrs() {
            let (k, _) = a?;
            r.unknown_attr(tag, k)?;
        }
        while r.peek_child()? == Some("ArgumentRestriction") {
            v.argument_restriction.push(r.read_child()?);
        }
        if v.argument_restriction.len() < 1 {
            let n = v.argument_restriction.len();
            return Err(r.too_few("ArgumentRestriction", 1, n));
        }
        r.close()?;
        Ok(v)
    }
}

