pub struct ContextSignificanceType {
    /// Describe the context matching value and source that will enable the
    /// Significance listed in the Significance element.
    pub context_match: ContextMatchType,
    /// Describe the signficance of this MetaCommand definition. See
    /// SignificanceType.
    pub significance: SignificanceType,
}

impl XmlElement for ContextSignificanceType {
    fn write_xml(&self, w: &mut Writer<'_>, tag: &str) -> Result<()> {
        w.start(tag);
        self.context_match.write_xml(w, "ContextMatch")?;
        self.significance.write_xml(w, "Significance")?;
        w.end(tag);
        Ok(())
    }

    fn read_xml<'a>(r: &mut Reader<'a>, tag: &Tag<'a>) -> Result<Self> {
        let mut v = Self::default();
        for a in tag.attrs() {
            let (k, _) = a?;
            r.unknown_attr(tag, k)?;
        }
        if r.peek_child()? != Some("ContextMatch") {
            return Err(r.expected("ContextMatch"));
        }
        v.context_match = r.read_child()?;
        if r.peek_child()? != Some("Significance") {
            return Err(r.expected("Significance"));
        }
        v.significance = r.read_child()?;
        r.close()?;
        Ok(v)
    }
}

/// Describe a custom, algorithmic alarm condition. The algorithm is assumed to
/// return a boolean value: true or false. See AlarmType.
#[derive(Debug, Clone, PartialEq, Default)]
pub struct CustomAlarmType {
    /// The alarm definition may be named.
    pub name: Option<String>,
    /// An optional brief description of this alarm definition.
    pub short_description: Option<String>,
    /// Element `AncillaryDataSet`.
    pub ancillary_data_set: Option<AncillaryDataSetType>,
    /// Algorithm returns a boolean.
    pub input_algorithm: InputAlgorithmType,
}

impl XmlElement for CustomAlarmType {
    fn write_xml(&self, w: &mut Writer<'_>, tag: &str) -> Result<()> {
        w.start(tag);
        if let Some(v) = &self.name {
            w.attr("name", v);
        }
        if let Some(v) = &self.short_description {
            w.attr("shortDescription", v);
        }
        if let Some(v) = &self.ancillary_data_set {
            v.write_xml(w, "AncillaryDataSet")?;
        }
        self.input_algorithm.write_xml(w, "InputAlgorithm")?;
        w.end(tag);
        Ok(())
    }

    fn read_xml<'a>(r: &mut Reader<'a>, tag: &Tag<'a>) -> Result<Self> {
        let mut v = Self::default();
        for a in tag.attrs() {
            let (k, raw) = a?;
            match k {
                "name" => v.name = Some(r.attr_value(tag, raw)?),
                "shortDescription" => {
                    v.short_description = Some(r.attr_value(tag, raw)?)
                }
                _ => r.unknown_attr(tag, k)?,
            }
        }
        if r.peek_child()? == Some("AncillaryDataSet") {
            v.ancillary_data_set = Some(r.read_child()?);
        }
        if r.peek_child()? != Some("InputAlgorithm") {
            return Err(r.expected("InputAlgorithm"));
        }
        v.input_algorithm = r.read_child()?;
        r.close()?;
        Ok(v)
    }
}

/// A stream type where some level of custom processing (e.g. convolutional,
/// encryption, compression) is performed. Has a reference to external
/// algorithms for encoding and decoding algorithms.
#[derive(Debug, Clone, PartialEq, Default)]
pub struct CustomStreamType {
    /// Optional short description to be used for explanation of this item. It
    /// is recommended that the short description be kept under 80 characters in
    /// length.
    pub short_description: Option<String>,
    /// The name of this defined item. See NameType for restriction information.
    pub name: String,
    /// Attribute `bitRateInBPS`.
    pub bit_rate_in_bps: Option<f64>,
    /// Attribute `pcmType`.
    ///
    /// Schema default: `NRZL`.
    pub pcm_type: Option<PCMType>,
    /// Attribute `inverted`.
    ///
    /// Schema default: `false`.
    pub inverted: Option<bool>,
    /// Attribute `encodedStreamRef`.
    pub encoded_stream_ref: String,
    /// Attribute `decodedStreamRef`.
    pub decoded_stream_ref: String,
    /// Optional long form description to be used for explanatory descriptions
    /// of this item and may include HTML markup using CDATA. Long Descriptions
    /// are of unbounded length.
    pub long_description: Option<String>,
    /// Used to contain an alias (alternate) name or ID for this item. See
    /// AliasSetType for additional explanation.
    pub alias_set: Option<AliasSetType>,
    /// Use for any non-standard data associated with this named item. See
    /// AncillaryDataSetType for additional explanation.
    pub ancillary_data_set: Option<AncillaryDataSetType>,
    /// Element `EncodingAlgorithm`.
    pub encoding_algorithm: InputAlgorithmType,
    /// Algorithm outputs may be used to set decoding quality parameters.
    pub decoding_algorithm: InputOutputAlgorithmType,
}

impl XmlElement for CustomStreamType {
    fn write_xml(&self, w: &mut Writer<'_>, tag: &str) -> Result<()> {
        w.start(tag);
        if let Some(v) = &self.short_description {
            w.attr("shortDescription", v);
        }
        w.attr("name", &self.name);
        if let Some(v) = &self.bit_rate_in_bps {
            w.attr("bitRateInBPS", v);
        }
        if let Some(v) = &self.pcm_type {
            w.attr("pcmType", v);
        }
        if let Some(v) = &self.inverted {
            w.attr("inverted", v);
        }
        w.attr("encodedStreamRef", &self.encoded_stream_ref);
        w.attr("decodedStreamRef", &self.decoded_stream_ref);
        if let Some(v) = &self.long_description {
            w.leaf("LongDescription", v);
        }
        if let Some(v) = &self.alias_set {
            v.write_xml(w, "AliasSet")?;
        }
        if let Some(v) = &self.ancillary_data_set {
            v.write_xml(w, "AncillaryDataSet")?;
        }
        self.encoding_algorithm.write_xml(w, "EncodingAlgorithm")?;
        self.decoding_algorithm.write_xml(w, "DecodingAlgorithm")?;
        w.end(tag);
        Ok(())
    }

    fn read_xml<'a>(r: &mut Reader<'a>, tag: &Tag<'a>) -> Result<Self> {
        let mut v = Self::default();
        let mut seen_name = false;
        let mut seen_encoded_stream_ref = false;
        let mut seen_decoded_stream_ref = false;
        for a in tag.attrs() {
            let (k, raw) = a?;
            match k {
                "shortDescription" => {
                    v.short_description = Some(r.attr_value(tag, raw)?)
                }
                "name" => {
                    v.name = r.attr_value(tag, raw)?;
                    seen_name = true;
                }
                "bitRateInBPS" => {
                    v.bit_rate_in_bps = Some(r.attr_value(tag, raw)?)
                }
                "pcmType" => v.pcm_type = Some(r.attr_value(tag, raw)?),
                "inverted" => v.inverted = Some(r.attr_value(tag, raw)?),
                "encodedStreamRef" => {
                    v.encoded_stream_ref = r.attr_value(tag, raw)?;
                    seen_encoded_stream_ref = true;
                }
                "decodedStreamRef" => {
                    v.decoded_stream_ref = r.attr_value(tag, raw)?;
                    seen_decoded_stream_ref = true;
                }
                _ => r.unknown_attr(tag, k)?,
            }
        }
        if !seen_name {
            return Err(r.missing_attr(tag, "name"));
        }
        if !seen_encoded_stream_ref {
            return Err(r.missing_attr(tag, "encodedStreamRef"));
        }
        if !seen_decoded_stream_ref {
            return Err(r.missing_attr(tag, "decodedStreamRef"));
        }
        if r.peek_child()? == Some("LongDescription") {
            v.long_description = Some(r.read_leaf()?);
        }
        if r.peek_child()? == Some("AliasSet") {
            v.alias_set = Some(r.read_child()?);
        }
        if r.peek_child()? == Some("AncillaryDataSet") {
            v.ancillary_data_set = Some(r.read_child()?);
        }
        if r.peek_child()? != Some("EncodingAlgorithm") {
            return Err(r.expected("EncodingAlgorithm"));
        }
        v.encoding_algorithm = r.read_child()?;
        if r.peek_child()? != Some("DecodingAlgorithm") {
            return Err(r.expected("DecodingAlgorithm"));
        }
        v.decoding_algorithm = r.read_child()?;
        r.close()?;
        Ok(v)
    }
}

