/// For streams that contain a series of frames with a fixed frame length where
/// the frames are found by looking for a marker in the data. This marker is
/// sometimes called the frame sync pattern and sometimes the Asynchronous Sync
/// Marker (ASM). This marker need not be contiguous although it usually is.
#[derive(Debug, Clone, PartialEq, Default)]
pub struct FixedFrameStreamType {
    /// Optional short description to be used for explanation of this item. It
    /// is recommended that the short description be kept under 80 characters in
    /// length.
    pub short_description: Option<String>,
    /// The name of this defined item. See NameType for restriction information.
    pub name: String,
    /// Attribute `bitRateInBPS`.
    pub bit_rate_in_bps: Option<f64>,
    /// Attribute `pcmType`.
    ///
    /// Schema default: `NRZL`.
    pub pcm_type: Option<PCMType>,
    /// Attribute `inverted`.
    ///
    /// Schema default: `false`.
    pub inverted: Option<bool>,
    /// Allowed slip (in bits) in either direction for the sync pattern
    ///
    /// Schema default: `0`.
    pub sync_aperture_in_bits: Option<i64>,
    /// Attribute `frameLengthInBits`.
    pub frame_length_in_bits: i64,
    /// Optional long form description to be used for explanatory descriptions
    /// of this item and may include HTML markup using CDATA. Long Descriptions
    /// are of unbounded length.
    pub long_description: Option<String>,
    /// Used to contain an alias (alternate) name or ID for this item. See
    /// AliasSetType for additional explanation.
    pub alias_set: Option<AliasSetType>,
    /// Use for any non-standard data associated with this named item. See
    /// AncillaryDataSetType for additional explanation.
    pub ancillary_data_set: Option<AncillaryDataSetType>,
    /// One of: `ContainerRef`, `ServiceRef`.
    pub choice: FixedFrameStreamChoice,
    /// This is a reference to a connecting stream - say a custom stream.
    pub stream_ref: Option<StreamRefType>,
    /// Element `SyncStrategy`.
    pub sync_strategy: FixedFrameSyncStrategyType,
}

impl XmlElement for FixedFrameStreamType {
    fn write_xml(&self, w: &mut Writer<'_>, tag: &str) -> Result<()> {
        w.start(tag);
        if let Some(v) = &self.short_description {
            w.attr("shortDescription", v);
        }
        w.attr("name", &self.name);
        if let Some(v) = &self.bit_rate_in_bps {
            w.attr("bitRateInBPS", v);
        }
        if let Some(v) = &self.pcm_type {
            w.attr("pcmType", v);
        }
        if let Some(v) = &self.inverted {
            w.attr("inverted", v);
        }
        if let Some(v) = &self.sync_aperture_in_bits {
            w.attr("syncApertureInBits", v);
        }
        w.attr("frameLengthInBits", &self.frame_length_in_bits);
        if let Some(v) = &self.long_description {
            w.leaf("LongDescription", v);
        }
        if let Some(v) = &self.alias_set {
            v.write_xml(w, "AliasSet")?;
        }
        if let Some(v) = &self.ancillary_data_set {
            v.write_xml(w, "AncillaryDataSet")?;
        }
        self.choice.write_xml(w)?;
        if let Some(v) = &self.stream_ref {
            v.write_xml(w, "StreamRef")?;
        }
        self.sync_strategy.write_xml(w, "SyncStrategy")?;
        w.end(tag);
        Ok(())
    }

    fn read_xml<'a>(r: &mut Reader<'a>, tag: &Tag<'a>) -> Result<Self> {
        let mut v = Self::default();
        let mut seen_name = false;
        let mut seen_frame_length_in_bits = false;
        for a in tag.attrs() {
            let (k, raw) = a?;
            match k {
                "shortDescription" => {
                    v.short_description = Some(r.attr_value(tag, raw)?)
                }
                "name" => {
                    v.name = r.attr_value(tag, raw)?;
                    seen_name = true;
                }
                "bitRateInBPS" => {
                    v.bit_rate_in_bps = Some(r.attr_value(tag, raw)?)
                }
                "pcmType" => v.pcm_type = Some(r.attr_value(tag, raw)?),
                "inverted" => v.inverted = Some(r.attr_value(tag, raw)?),
                "syncApertureInBits" => {
                    v.sync_aperture_in_bits = Some(r.attr_value(tag, raw)?)
                }
                "frameLengthInBits" => {
                    v.frame_length_in_bits = r.attr_value(tag, raw)?;
                    seen_frame_length_in_bits = true;
                }
                _ => r.unknown_attr(tag, k)?,
            }
        }
        if !seen_name {
            return Err(r.missing_attr(tag, "name"));
        }
        if !seen_frame_length_in_bits {
            return Err(r.missing_attr(tag, "frameLengthInBits"));
        }
        if r.peek_child()? == Some("LongDescription") {
            v.long_description = Some(r.read_leaf()?);
        }
        if r.peek_child()? == Some("AliasSet") {
            v.alias_set = Some(r.read_child()?);
        }
        if r.peek_child()? == Some("AncillaryDataSet") {
            v.ancillary_data_set = Some(r.read_child()?);
        }
        v.choice = FixedFrameStreamChoice::read_xml(r)?;
        if r.peek_child()? == Some("StreamRef") {
            v.stream_ref = Some(r.read_child()?);
        }
        if r.peek_child()? != Some("SyncStrategy") {
            return Err(r.expected("SyncStrategy"));
        }
        v.sync_strategy = r.read_child()?;
        r.close()?;
        Ok(v)
    }
}

