#[derive(Debug, Clone, PartialEq, Default)]
pub struct InputSetType {
    /// One of: `InputParameterInstanceRef`, `Constant`.
    pub items: Vec<InputSetChoice>,
}

impl XmlElement for InputSetType {
    fn write_xml(&self, w: &mut Writer<'_>, tag: &str) -> Result<()> {
        w.start(tag);
        check_count(self.items.len(), 1, None, "InputSetType.InputSetChoice")?;
        for v in &self.items {
            v.write_xml(w)?;
        }
        w.end(tag);
        Ok(())
    }

    fn read_xml<'a>(r: &mut Reader<'a>, tag: &Tag<'a>) -> Result<Self> {
        let mut v = Self::default();
        for a in tag.attrs() {
            let (k, _) = a?;
            r.unknown_attr(tag, k)?;
        }
        while r.peek_child()?.is_some_and(InputSetChoice::accepts) {
            v.items.push(InputSetChoice::read_xml(r)?);
        }
        if v.items.len() < 1 {
            let n = v.items.len();
            return Err(r.too_few("InputParameterInstanceRef|Constant", 1, n));
        }
        r.close()?;
        Ok(v)
    }
}

