/// Describe an unordered collection of parameters where duplicates defined by
/// the Parameter name attribute are invalid. The ParameterSet exists in both
/// the TelemetryMetaData and the CommandMetaData element so that each may be
/// built independently but from a single namespace. See TelemetryMetaDataType
/// and CommandMetaDataType.
#[derive(Debug, Clone, PartialEq, Default)]
pub struct ParameterSetType {
    /// One of: `Parameter`, `ParameterRef`.
    pub items: Vec<ParameterSetChoice>,
}

impl XmlElement for ParameterSetType {
    fn write_xml(&self, w: &mut Writer<'_>, tag: &str) -> Result<()> {
        w.start(tag);
        check_count(
            self.items.len(),
            1,
            None,
            "ParameterSetType.ParameterSetChoice",
        )?;
        for v in &self.items {
            v.write_xml(w)?;
        }
        w.end(tag);
        Ok(())
    }

    fn read_xml<'a>(r: &mut Reader<'a>, tag: &Tag<'a>) -> Result<Self> {
        let mut v = Self::default();
        for a in tag.attrs() {
            let (k, _) = a?;
            r.unknown_attr(tag, k)?;
        }
        while r.peek_child()?.is_some_and(ParameterSetChoice::accepts) {
            v.items.push(ParameterSetChoice::read_xml(r)?);
        }
        if v.items.len() < 1 {
            let n = v.items.len();
            return Err(r.too_few("Parameter|ParameterRef", 1, n));
        }
        r.close()?;
        Ok(v)
    }
}

