/// A service is a logical grouping of container and/or messages.
#[derive(Debug, Clone, PartialEq, Default)]
pub struct ServiceSetType {
    /// Element `Service`.
    pub service: Vec<ServiceType>,
}

impl XmlElement for ServiceSetType {
    fn write_xml(&self, w: &mut Writer<'_>, tag: &str) -> Result<()> {
        w.start(tag);
        check_count(self.service.len(), 1, None, "ServiceSetType.Service")?;
        for v in &self.service {
            v.write_xml(w, "Service")?;
        }
        w.end(tag);
        Ok(())
    }

    fn read_xml<'a>(r: &mut Reader<'a>, tag: &Tag<'a>) -> Result<Self> {
        let mut v = Self::default();
        for a in tag.attrs() {
            let (k, _) = a?;
            r.unknown_attr(tag, k)?;
        }
        while r.peek_child()? == Some("Service") {
            v.service.push(r.read_child()?);
        }
        if v.service.len() < 1 {
            let n = v.service.len();
            return Err(r.too_few("Service", 1, n));
        }
        r.close()?;
        Ok(v)
    }
}

