#[derive(Debug, Clone, PartialEq, Default)]
pub struct TriggeredMathOperationType {
    /// Optional name for this calibrator/algorithm
    pub name: Option<String>,
    /// Optional description for this calibrator/algorithm
    pub short_description: Option<String>,
    /// Attribute `outputParameterRef`.
    pub output_parameter_ref: String,
    /// Optional additional ancillary information for this calibrator/algorithm
    pub ancillary_data_set: Option<AncillaryDataSetType>,
    /// One of: `ValueOperand`, `ThisParameterOperand`, `Operator`,
    /// `ParameterInstanceRefOperand`.
    pub items: Vec<TriggeredMathOperationChoice>,
    /// Element `TriggerSet`.
    pub trigger_set: TriggerSetType,
}

impl XmlElement for TriggeredMathOperationType {
    fn write_xml(&self, w: &mut Writer<'_>, tag: &str) -> Result<()> {
        w.start(tag);
        if let Some(v) = &self.name {
            w.attr("name", v);
        }
        if let Some(v) = &self.short_description {
            w.attr("shortDescription", v);
        }
        w.attr("outputParameterRef", &self.output_parameter_ref);
        if let Some(v) = &self.ancillary_data_set {
            v.write_xml(w, "AncillaryDataSet")?;
        }
        check_count(
            self.items.len(),
            1,
            None,
            "TriggeredMathOperationType.TriggeredMathOperationChoice",
        )?;
        for v in &self.items {
            v.write_xml(w)?;
        }
        self.trigger_set.write_xml(w, "TriggerSet")?;
        w.end(tag);
        Ok(())
    }

    fn read_xml<'a>(r: &mut Reader<'a>, tag: &Tag<'a>) -> Result<Self> {
        let mut v = Self::default();
        let mut seen_output_parameter_ref = false;
        for a in tag.attrs() {
            let (k, raw) = a?;
            match k {
                "name" => v.name = Some(r.attr_value(tag, raw)?),
                "shortDescription" => {
                    v.short_description = Some(r.attr_value(tag, raw)?)
                }
                "outputParameterRef" => {
                    v.output_parameter_ref = r.attr_value(tag, raw)?;
                    seen_output_parameter_ref = true;
                }
                _ => r.unknown_attr(tag, k)?,
            }
        }
        if !seen_output_parameter_ref {
            return Err(r.missing_attr(tag, "outputParameterRef"));
        }
        if r.peek_child()? == Some("AncillaryDataSet") {
            v.ancillary_data_set = Some(r.read_child()?);
        }
        while r
            .peek_child()?
            .is_some_and(TriggeredMathOperationChoice::accepts)
        {
            v.items.push(TriggeredMathOperationChoice::read_xml(r)?);
        }
        if v.items.len() < 1 {
            let n = v.items.len();
            return Err(r.too_few(
                "ValueOperand|ThisParameterOperand|\
                        Operator|ParameterInstanceRefOperand",
                1,
                n,
            ));
        }
        if r.peek_child()? != Some("TriggerSet") {
            return Err(r.expected("TriggerSet"));
        }
        v.trigger_set = r.read_child()?;
        r.close()?;
        Ok(v)
    }
}

