        for a in tag.attrs() {
            let (k, raw) = a?;
            match k {
                "validRangeAppliesToCalibrated" => {
                    v.valid_range_applies_to_calibrated =
                        Some(r.attr_value(tag, raw)?)
                }
                _ => r.unknown_attr(tag, k)?,
            }
        }
        while r.peek_child()? == Some("ValidRange") {
            v.valid_range.push(r.read_child()?);
        }
        if v.valid_range.len() < 1 {
            let n = v.valid_range.len();
            return Err(r.too_few("ValidRange", 1, n));
        }
        r.close()?;
        Ok(v)
